Assertions:
[BODY] link_buyer_identity returns 200; link_result.buyer_id equals the Platform user's platform_id for @td(ACME_ADMIN.email); link_result.organization_id equals @td(ORG_ACME.platform_id) {SPEC}
[MATH] cart.total equals first_product.price x 1 (2 decimal places) {BL}
[BODY] handoff.checkout.id equals cart.id {SPEC}
[NAV] browser URL matches /cart/{cart.id}\?ucp_handoff=1 after opening continue_url {OBSERVED}
[REL] the storefront cart's line items and total equal cart.id / cart.total captured from the MCP leg {SPEC}
[DOM] the storefront cart shows organization context consistent with @td(ORG_ACME.platform_id) (org-scoped view, not an anonymous one) {SPEC}

[ERRORS label=plat1] HTTP 200 {OBSERVED}
[ERRORS label=sf1] HTTP 200 {OBSERVED}
[DATA label=sf1] body.ucp.version = {{PLAT_UCP_VERSION}} {OBSERVED} -- both hosts serve the same manifest version; a split here is the 2026-09-17 origin drift (domain map D2) reproducing
[DATA label=sf1] body.ucp.status = success {OBSERVED}
[ERRORS label=plat_prm] HTTP 200 {OBSERVED} -- the Platform host publishes RFC 9728 metadata for the UCP resource even though the resource itself lives on the storefront
[ERRORS label=sf_prm] HTTP 200 {OBSERVED}
[DATA label=sf_prm] body.resource = {{PLAT_RESOURCE}} {OBSERVED} -- the two hosts name the SAME resource; this is the actual D2 no-drift proof
[DATA label=sf_prm] body.authorization_servers.0 = {{PLAT_AS}} {OBSERVED} -- and the same authorization server
[DATA label=sf_prm] body.resource = {{FRONT_URL}}/ucp/mcp {OBSERVED} -- and the resource they agree on is the storefront endpoint this suite actually mints tokens against, not the Platform host
[DATA label=caps1] body.storefront_origin = {{FRONT_URL}} {OBSERVED} -- the get_store_capabilities tool (the only surface that carries storefront_origin) agrees with the host serving it
[ERRORS label=mcp_init] HTTP 200 {OBSERVED} -- the resource the metadata names actually answers a real JSON-RPC initialize call
[ERRORS label=mcp_tlist] HTTP 200 {OBSERVED} -- and a real tools/list call, on that same host

[ERRORS label=search1] HTTP 200 {SPEC} -- ordinary anonymous shopping is not gated behind link_buyer_identity (architecture comment: no token means anonymous)
[ERRORS label=cart1] HTTP 200 {SPEC}
[DATA label=cart1] body.cart.buyer_id matches /^ucp-anonymous-[0-9a-f]{32}$/ {SPEC}

[ERRORS label=link1] HTTP 200 {SPEC}
[DATA label=link1] body.organization_id is null {SPEC} -- architecture comment: identity only from ClaimsPrincipal
[NULL label=link1] body.organization_id {SPEC} -- no organization is invented for a buyer who has none

[ERRORS label=link1] HTTP 200 {SPEC}
[DATA label=link1] body.buyer_id = @td(ACME_ADMIN.platform_id) {SPEC}
[DATA label=link1] body.organization_id = @td(ORG_ACME.platform_id) {SPEC}
[ERRORS label=link2] HTTP 200 {BL}
[DATA label=link2] body.organization_id = @td(ORG_ACME.platform_id) {BL} -- the forged argument's organization_id is IGNORED; only the token sets identity (BL-AUTH-015)

[DATA label=cart1] body.cart.buyer_id matches /^ucp-anonymous-[0-9a-f]{32}$/ {SPEC}
[ERRORS label=get1] HTTP 200 {SPEC}
[DATA label=get1] body.cart.id = {{CART_ID}} {SPEC} -- the second get_cart call, replaying the same synthetic id, resolves the SAME cart

[ERRORS label=link] HTTP 200 {SPEC}
[DATA label=link] body.linked = true {OBSERVED}
[ERRORS label=cart1] HTTP 200 {SPEC}
[DATA label=cart1] body.cart.buyer_id = {{LINKED_BUYER_ID}} {SPEC}
[NULL label=cart1] body.cart.organization_id {SPEC}

[ERRORS label=link] HTTP 200 {SPEC}
[DATA label=link] body.linked = true {OBSERVED}
[DATA label=cart1] body.cart.buyer_id = @td(ACME_ADMIN.platform_id) {SPEC}
[DATA label=cart1] body.cart.organization_id = @td(ORG_ACME.platform_id) {SPEC}

[ERRORS label=link] HTTP 200 {SPEC}
[DATA label=link] body.linked = true {OBSERVED}
[COUNT label=cart1] body.cart.line_items.length = 1 {BL} -- and exactly the line this case composed, nothing carried over
[DATA label=cart1] body.cart.line_items[?product_id={{P1_ID}}].quantity = 2 {BL}
[DATA label=cart1] body.cart.line_items[?product_id={{P1_ID}}].unit_price.amount = {{P1_PRICE}} {BL} -- the line carries the unit price search_products advertised for it
[DATA label=cart1] body.cart.line_items[?product_id={{P1_ID}}].line_total.amount = {{P1_PRICE}} * 2 {BL} -- line_total is unit_price x quantity, not a separately-sourced number
[DATA label=cart1] body.cart.totals.total.amount = {{P1_PRICE}} * 2 {BL} -- and the cart total is that one line, the cart having been emptied first
[DATA label=co1] body.checkout.cart.totals.total.amount = {{CART_TOTAL}} {BL} -- the checkout snapshot must not drift from the cart it snapshots (delegated BL-CART-002/BL-CHK-001). NOTE the path: create_checkout WRAPS the cart, so the totals are at checkout.cart.totals, not checkout.totals — the earlier form of this case asserted checkout.totals.total.amount and read undefined
[DATA label=co1] body.checkout.cart_id = {{CART_ID}} {OBSERVED} -- and it snapshots the cart this case actually composed

[ERRORS label=link] HTTP 200 {SPEC}
[DATA label=link] body.linked = true {OBSERVED}
[DATA label=cah1] body.continue_url matches /^{{FRONT_URL}}\// {OBSERVED} -- the issued continue_url is minted on the SAME host the capabilities/manifest endpoints advertise; confirmed live 2026-09-22 that the 2026-09-17 origin drift (domain map D2) no longer reproduces
[EVIDENCE] handoff.continue_url's expires_at is mint time plus the configured 15-minute TTL -- not independently re-verified by THIS case (no date-arithmetic predicate exists in the current DATA grammar); UCPA-021 exercises the TTL boundary directly and is the case that would catch a TTL regression

[ERRORS label=link] HTTP 200 {SPEC}
[DATA label=link] body.linked = true {OBSERVED}
[DATA label=merged] body.cart.buyer_id = @td(ACME_ADMIN.platform_id) {SPEC} -- the buyer now owns the cart, not the synthetic anonymous id
[DATA label=merged] body.cart.totals.total.amount = {{ANON_TOTAL}} {SPEC} -- items carried at the same total, no duplication
[DATA label=probe] body.code = cart_not_found {SPEC} -- the anonymous source cart no longer resolves (deleteAfterMerge); UCP's own declared error-code vocabulary names this case
[DATA label=replay] body.cart.totals.total.amount = {{ANON_TOTAL}} {SPEC} -- the replayed merge is an idempotent no-op, not a duplication

[ERRORS label=link] HTTP 200 {SPEC}
[DATA label=link] body.linked = true {OBSERVED}
[COUNT label=anon_scoped] body.products.length = 0 {OBSERVED} -- the assortment-scoped product is invisible anonymously (proven live via seed-org-contract:verify)
[COUNT label=buyer_scoped] body.products.length >= 1 {OBSERVED} -- the same product IS visible to the contract buyer
[COUNT label=anon_control] body.products.length >= 1 {SPEC}
[COUNT label=buyer_control] body.products.length >= 1 {SPEC} -- the control is equally visible in both contexts, proving the scoped product's absence is the assortment rule and not a general catalog/auth fault (SECOND RULE control)

[ERRORS label=link] HTTP 200 {SPEC}
[DATA label=link] body.linked = true {OBSERVED}
[DATA label=anon_price] body.products.0.price.amount = @td(UCP_CONTRACT_PRODUCT.anonymous_price_minor) {OBSERVED}
[DATA label=buyer_price] body.products.0.price.amount = @td(UCP_CONTRACT_PRODUCT.contract_price_minor) {OBSERVED} -- proven live
[DATA label=buyer_price] {{ANON_PRICE}} - body.products.0.price.amount = @td(UCP_CONTRACT_PRODUCT.price_delta_minor) {BL} -- assert the DELTA by alias, never a literal
[DATA label=buyer_control_price] body.products.0.price.amount = {{ANON_CONTROL_PRICE}} {SPEC} -- the control prices IDENTICALLY in both contexts, proving the delta above is the contract and not a general anonymous-vs-authenticated discount (SECOND RULE control)

