[ERRORS label=link] HTTP 200 {SPEC}
[DATA label=link] body.linked = true {OBSERVED}
[NULL label=create_checkout_a] body.continue_url {OBSERVED}
[NULL label=create_checkout_a] body.checkout.continue_url {OBSERVED}
[DATA label=handoff_checkout_b] body.result.checkout.continue_url is non-null {OBSERVED} -- double-wrapped shape
[DATA label=cah_c] body.continue_url is non-null {OBSERVED} -- the only tool with a top-level continue_url
